def word_wrap(text, width):
    if not text or not text.strip():
        return []
    lines = []
    current = []
    current_len = 0
    for word in text.split():
        word_len = len(word)
        if current and current_len + 1 + word_len > width:
            lines.append(' '.join(current))
            current = [word]
            current_len = word_len
        else:
            if current:
                current_len += 1 + word_len
            else:
                current_len = word_len
            current.append(word)
    if current:
        lines.append(' '.join(current))
    return lines
